import { useEffect, useRef, useState } from 'react';
import { Globe2 } from 'lucide-react';
import './VisitorMap.css';

type VisitorMapProps = {
  /** The map.js URL generated by MapMyVisitors for this website. */
  widgetSrc: string;
};

export default function VisitorMap({ widgetSrc }: VisitorMapProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Defer insertion so React StrictMode's first effect cleanup cancels it.
    const timeout = window.setTimeout(() => {
      const script = document.createElement('script');
      script.id = 'mapmyvisitors';
      script.src = widgetSrc;
      script.async = true;
      script.onerror = () => setFailed(true);
      container.appendChild(script);
    }, 0);

    return () => {
      window.clearTimeout(timeout);
      container.replaceChildren();
    };
  }, [widgetSrc]);

  return (
    <section className="visitor-section" aria-labelledby="visitor-map-title">
      <div className="visitor-heading">
        <Globe2 size={20} aria-hidden="true" />
        <h2 id="visitor-map-title">Visitors around the world</h2>
      </div>
      <p className="visitor-intro">Thanks for stopping by, wherever you are.</p>
      <div className="visitor-map-frame">
        <div ref={containerRef} className="visitor-map-widget" />
        {failed && (
          <p className="visitor-map-error" role="status">
            The visitor map is temporarily unavailable. Please try again later.
          </p>
        )}
      </div>
      <a
        className="visitor-credit"
        href="https://mapmyvisitors.com/"
        target="_blank"
        rel="noopener noreferrer"
      >
        Powered by MapMyVisitors
      </a>
    </section>
  );
}
